<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Entropy Checker','description'=>'Estimate password entropy and strength locally in your browser.','url'=>'https://smarttoolz.in/tools/password-entropy-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Password Entropy Checker</h1><p>Estimate the search-space entropy of a password.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="p" type="password" placeholder="Enter password"><button id="go" class="tool-btn">Check Strength</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let s=p.value,n=0;if(/[a-z]/.test(s))n+=26;if(/[A-Z]/.test(s))n+=26;if(/[0-9]/.test(s))n+=10;if(/[^A-Za-z0-9]/.test(s))n+=32;let e=n&&s.length?Math.log2(n)*s.length:0;o.textContent=`Estimated entropy: ${e.toFixed(1)} bits · ${e<40?'Weak':e<60?'Moderate':e<80?'Strong':'Very strong'}`}</script><?php smarttoolz_tool_page_end(); ?>